ree"]}},"required":["type"]}]}},"additionalProperties":false}},{"name":"get_usage_limits","description":"Read current Codex usage limits for the ChatGPT account signed in on this task's host. Use for questions about usage percentages, remaining limits, or reset times. These limits are shared across the account, not specific to this task. Each window's usedPercent is the percentage consumed; remaining percent is 100 minus usedPercent, clamped to 0-100. windowDurationMins is the window length in minutes and resetsAt is a Unix timestamp in seconds. Prefer rateLimitsByLimitId when available; rateLimits is the legacy single-bucket view. Null or missing values mean unavailable, not zero usage. This read-only tool does not consume a reset or purchase credits.","inputSchema":{"type":"object","properties":{},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}]},{"hostId":"local","icon":null,"pluginId":null,"server":"codex_apps","tools":[{"name":"sites.list_custom_domains","title":"list_custom_domains","description":"List custom domains attached to a site. This tool is part of plugin `Sites`.","inputSchema":{"type":"object","properties":{"project_id":{"description":"Exact opaque site project ID. Copy it verbatim from .openai/hosting.json's project_id or the id field returned by create_site, list_sites, or get_site, or the server-returned site_metadata.project_id on a Library Site result. Keep the same selected workspace. Never invent, modify, or substitute another identifier.","title":"Project Id","type":"string"}},"required":["project_id"],"title":"AppgardenProjectRequest","additionalProperties":false},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false},"_meta":{"resource_name":"sites.list_custom_domains","_codex_apps":{"resource_uri":"/connector_20205bf7d4e99a89d7154bb849718324/implicit_link::connector_20205bf7d4e99a89d7154bb849718324/list_custom_domains","contains_mcp_source":false},"connector_id":"connector