ting.json or Sites responses as applicable, and never invent, reformat, derive, or substitute them. Never call create_site more than once for the same local site. Push the exact source state before saving a version. commit_sha must identify that pushed state, and any archive must be built from it. Deploy only saved versions; every Sites deployment URL is production. Inspect deployment status when the initial result is non-terminal or the user asks for progress. Publish after creating or editing a site by default, including on subsequent turns, unless the user explicitly requested local-only work, a saved version without deployment, or no publishing. New sites start private. Preserve the site's current audience unless the user explicitly requests a different audience. Use the private operation for known owner-private sites and let it enforce owner-only access. Runtime tool approvals and backend access checks still apply without a separate conversational deployment confirmation.","link_id":"implicit_link::connector_20205bf7d4e99a89d7154bb849718324"},"outputSchema":{"properties":{"project_id":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Project Id"},"bindings":{"items":{"type":"string"},"title":"Bindings","type":"array"},"selected_binding_name":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Selected Binding Name"},"tables":{"items":{"type":"string"},"title":"Tables","type":"array"},"model_projection":{"properties":{"truncated":{"title":"Truncated","type":"boolean"},"omitted_project_id":{"title":"Omitted Project Id","type":"boolean"},"omitted_selected_binding":{"title":"Omitted Selected Binding","type":"boolean"},"omitted_bindings":{"title":"Omitted Bindings","type":"integer"},"omitted_tables":{"title":"Omitted Tables","type":"integer"}},"required":["truncated","omitted_project_id","omitted_selected_binding","omitted_bindings","omitted_tables"],"title":"DatabaseOverviewModelProjectionInfo","type":"object","additionalProperties":false}},"required":["proje