ct_id.","title":"Project Id","type":"string"},"title":{"title":"Title","type":"string"},"version_id":{"description":"Opaque saved version ID. Pass this exact value as version_id.","title":"Version Id","type":"string"},"type":{"enum":["preview","publish"],"title":"AppDeploymentKind","type":"string"},"status":{"enum":["pending","building","publishing","succeeded","failed"],"title":"AppDeploymentStatus","type":"string"},"url":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Url"},"screenshot_asset_pointer":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null,"title":"Screenshot Asset Pointer"},"provider_deployment_id":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Provider Deployment Id"},"failure_message":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Failure Message"},"env_set_revision":{"title":"Env Set Revision","type":"integer"},"updated_at":{"title":"Updated At","type":"string"}},"required":["id","project_id","title","version_id","type","status","url","provider_deployment_id","failure_message","env_set_revision","updated_at"],"title":"AppGardenDeploymentResponse","type":"object","additionalProperties":false}},{"name":"sites.delete_site","title":"delete_site","description":"Permanently delete a site. Use only when the user explicitly asks to delete the site. This does not unpublish or roll back a deployment and does not delete local files. This tool is part of plugin `Sites`.","inputSchema":{"type":"object","properties":{"project_id":{"description":"Exact opaque site project ID. Copy it verbatim from .openai/hosting.json's project_id or the id field returned by create_site, list_sites, or get_site, or the server-returned site_metadata.project_id on a Library Site result. Keep the same selected workspace. Never invent, modify, or substitute another identifier.","title":"Project Id","type":"string"}},"required":["project_id"],"title":"AppgardenProjectRequest","additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint