lity without strong buy intent. \"gift\" = buying for someone else. \"market_comparison\" = comparing prices or options across ticket marketplaces (e.g. \"are these tickets cheaper on SeatGeek?\").","type":"string","enum":["discovery","specific_search","purchase","price_check","gift","market_comparison"]}},"required":["eventId"],"$schema":"http://json-schema.org/draft-07/schema#"},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false},"_meta":{"openai/outputTemplate":"ui://widget/eventListings.html","ui/resourceUri":"ui://widget/eventListings.html","openai/widgetAccessible":true,"openai/toolInvocation/invoking":"Finding event listings","openai/toolInvocation/invoked":"Found event listings","ui":{"visibility":["model","app"],"resourceUri":"ui://widget/eventListings.html"},"resource_name":"seatgeek.eventListings","_codex_apps":{"resource_uri":"/asdk_app_69b21647523881919b220a29cea4dd3d/link_69d5a6e245c48191a49a48fecda1e110/eventListings","contains_mcp_source":true},"connector_id":"asdk_app_69b21647523881919b220a29cea4dd3d","connector_name":"SeatGeek","connector_description":"Buy event tickets","link_id":"link_69d5a6e245c48191a49a48fecda1e110"}},{"name":"sites.update_access","title":"update_access","description":"Deprecated legacy Codex app alias. Use update_site_access instead. This tool is part of plugin `Sites`.","inputSchema":{"type":"object","properties":{"project_id":{"description":"Workspace site project ID","title":"Project Id","type":"string"},"access_mode":{"description":"Required access mode for the site: workspace_all grants all active workspace users; custom uses the supplied user and group allowlists.","enum":["workspace_all","custom"],"title":"Access Mode","type":"string"},"allowed_user_emails":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"default":null,"description":"User email allowlist for the site.","title":"Allowed User Emails"},"allowed_workspace_group_ids":{"anyOf":[{"items":{"type":"string"},"ty