ng"},"filename":{"description":"Save snapshot to a file instead of returning it in the response. Relative file names are resolved against the workspace root.","type":"string"},"depth":{"description":"Limit the depth of the snapshot tree","type":"number"},"boxes":{"description":"Include each element's bounding box as [box=x,y,width,height] in the snapshot. Coordinates are viewport-relative, in CSS pixels (Element.getBoundingClientRect)","type":"boolean"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Page snapshot","readOnlyHint":true,"destructiveHint":false,"openWorldHint":true}},{"name":"browser_tabs","description":"List, create, close, or select a browser tab.","inputSchema":{"type":"object","properties":{"action":{"type":"string","enum":["list","new","close","select"],"description":"Operation to perform"},"index":{"description":"Tab index, used for close/select. If omitted for close, current tab is closed.","type":"number"},"url":{"description":"URL to navigate to in the new tab, used for new.","type":"string"}},"required":["action"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Manage tabs","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_run_code_unsafe","description":"Run a Playwright code snippet. Unsafe: executes arbitrary JavaScript in the Playwright server process and is RCE-equivalent.","inputSchema":{"type":"object","properties":{"code":{"description":"A JavaScript function containing Playwright code to execute. It will be invoked with a single argument, page, which you can use for any page interaction. For example: `async (page) => { await page.getByRole('button', { name: 'Submit' }).click(); return await page.title(); }`","type":"string"},"filename":{"description":"Load code from the specified file. Relative file names are resolved against the workspace root. If both code and filename are provided, code will be ignored.","type":"string"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Run Playwright code (unsafe)","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_type","description":"Type text into editable element","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"text":{"type":"string","description":"Text to type into the element"},"submit":{"description":"Whether to submit entered text (press Enter after)","type":"boolean"},"slowly":{"description":"Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once.","type":"boolean"}},"required":["target","text"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Type text","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_console_messages","description":"Returns all console messages","inputSchema":{"type":"object","properties":{"level":{"default":"info","description":"Level of the console messages to return. Each level includes the messages of more severe levels. Defaults to \"info\".","type":"string","enum":["error","warning","info","debug"]},"all":{"description":"Return all console messages since the beginning of the session, not just since the last navigation. Defaults to false.","type":"boolean"},"filename":{"description":"File name to save the console messages to. Relative file names are resolved against the workspace root. If not provided, messages are returned as text.","type":"string"}},"required":["level"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties