ement","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"doubleClick":{"description":"Whether to perform a double click instead of a single click","type":"boolean"},"button":{"description":"Button to click, defaults to left","type":"string","enum":["left","right","middle"]},"modifiers":{"description":"Modifier keys to press","type":"array","items":{"type":"string","enum":["Alt","Control","ControlOrMeta","Meta","Shift"]}}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Click","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_hover","description":"Hover over element on page","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Hover mouse","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_evaluate","description":"Evaluate JavaScript expression on page or element","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"description":"Exact target element reference from the page snapshot, or a unique element selector","type":"string"},"function":{"type":"string","description":"() => { /* code */ } or (element) => { /* code */ } when element is provided"},"filename":{"description":"File name to save the result to. Relative file names are resolved against the workspace root. If not provided, result is returned as text.","type":"string"}},"required":["function"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Evaluate JavaScript","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_close","description":"Close the page","inputSchema":{"type":"object","properties":{},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Close browser","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_handle_dialog","description":"Handle a dialog","inputSchema":{"type":"object","properties":{"accept":{"type":"boolean","description":"Whether to accept the dialog."},"promptText":{"description":"The text of the prompt in case of a prompt dialog.","type":"string"}},"required":["accept"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Handle a dialog","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_drag","description":"Perform drag and drop between two elements","inputSchema":{"type":"object","properties":{"startElement":{"description":"Human-readable source element description used to obtain the permission to interact with the element","type":"string"},"startTarget":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"endElement":{"description":"Human-readable target element description used to obtain the permission to interact with the element","type":"string"},"endTarget":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"}},"required":["startTarget","endTarget"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Drag mouse","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_drop","description":"Drop files or MIME-typed data onto an element, as if dragged from outside the page. At least one of \"paths\" or \"data\" must be provided.","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"paths":{"description":"Absolute paths to files to drop onto the element.","type":"array","items":{"type":"string"}},"data":{"description":"Data to drop, as a map of MIME type to string value (e.g. {\"text/plain\": \"hello\", \"text/uri-list\": \"https://example.com\"}).","type":"object","propertyNames":{"type":"string"},"additionalProperties":{"type":"string"}}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Drop files or data onto an element","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_navigate_back","description":"Go back to the previous page in the history","inputSchema":{"type":"object","properties":{},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Go back","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_select_option","description":"Select an option in a dropdown","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"values":{"type":"array","items":{"type":"string"},"description":"Array of values to select in the dropdown. This can be a single value or multiple values."}},"required":["target","values"],"$schema":"https://json-schema.org/draft/2020-12/schema",