eadIds":{"type":"array","items":{"type":"string","minLength":1},"description":"Every Codex task and ChatGPT conversation id in this section, listed exactly once in the desired order."}},"required":["sectionId","threadIds"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}},{"name":"end_realtime_voice_call","description":"End the current voice chat. Only call this tool if the user explicitly asks to end the voice chat.","inputSchema":{"type":"object","properties":{},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}},{"name":"delete_sidebar_section","description":"Delete a custom sidebar section. Its tasks and projects remain available outside the section.","inputSchema":{"type":"object","properties":{"sectionId":{"type":"string","minLength":1,"description":"Section id returned by list_threads."}},"required":["sectionId"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}},{"name":"list_projects","description":"List local, remote, and ChatGPT projects available for task creation, including whether each project is a Git repository. Use a returned projectId with create_thread and isGitRepository to choose the environment for local or remote projects.","inputSchema":{"type":"object","properties":{},"additionalProperties":false}},{"name":"load_workspace_dependencies","description":"Locate the configured bundled workspace dependency runtime paths for this local desktop thread, including Node.js, Python, and useful libraries for working with spreadsheets, slide decks, Word documents, and PDFs. This is read-only and takes no arguments.","inputSchema":{"type":"object","properties":{},"additionalProperties":false}},{"name":"move_thread_to_sidebar_section","description":"Move a Codex task between sidebar sections. Use sectionId \"pinned\" to pin it, a custom section id to organize it, or \"chats\", \"threads\", or null to return it to unpinned tasks. Use reorder_section