els, and URLs. Falls back to request metadata if not provided.","title":"Locale"}},"required":["search_query"],"title":"TrailNameSearchInput","type":"object"}},"title":"search_trails_by_nameArguments"},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false},"_meta":{"openai/toolInvocation/invoking":"Searching for trails","openai/toolInvocation/invoked":"Searched for trails","ui":{"visibility":["model"]},"resource_name":"alltrails.search_trails_by_name","_codex_apps":{"resource_uri":"/connector_68f1afc5a6008191a701eaaab428816c/link_694c6c29ad0c8191b3e60a4b213c0a4c/search_trails_by_name","contains_mcp_source":true},"connector_id":"connector_68f1afc5a6008191a701eaaab428816c","connector_name":"AllTrails","connector_description":"Enables discovery and exploration of outdoor trails (hiking, running, biking, backpacking, etc.) by searching near a point, within a geographic bounding box, near the user, or by trail name, with rich filters for conditions, difficulty, and suitability. Provides detailed trail information and a 7-day trailhead weather forecast for specific trails.","link_id":"link_694c6c29ad0c8191b3e60a4b213c0a4c"},"outputSchema":{"$defs":{"TrailSearchItem":{"properties":{"id":{"title":"Id","type":"integer"},"name":{"title":"Name","type":"string"},"slug":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null,"title":"Slug"},"alltrails_web_url":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null,"title":"Alltrails Web Url"},"has_profile_photo":{"title":"Has Profile Photo","type":"boolean"},"profile_photo_url":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null,"title":"Profile Photo Url"},"avg_rating":{"anyOf":[{"type":"number"},{"type":"null"}],"default":null,"title":"Avg Rating"},"duration_minutes":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":null,"title":"Duration Minutes"},"elevation_gain_meters":{"anyOf":[{"type":"number"},{"type":"null"}],"default":null,"title":"Elevation Gain Meters"},"elevation_gai