se,"title":"Is Secret","type":"boolean"},"type":{"const":"envvar","default":"envvar","title":"Type","type":"string"}},"required":["key","value"],"title":"AppgardenEnvironmentEnvVarEntryResponse","type":"object","additionalProperties":false},"title":"Entries","type":"array"},"revision":{"title":"Revision","type":"integer"},"updated_at":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Updated At"}},"required":["project_id","entries","revision","updated_at"],"title":"AppgardenEnvironmentResponse","type":"object","additionalProperties":false}},{"name":"sites.get_environment_variables","title":"get_environment_variables","description":"Get the production runtime environment variables for a site. These values are separate from local .env files and .openai/hosting.json. This tool is part of plugin `Sites`.","inputSchema":{"type":"object","properties":{"project_id":{"description":"Exact opaque site project ID. Copy it verbatim from .openai/hosting.json's project_id or the id field returned by create_site, list_sites, or get_site, or the server-returned site_metadata.project_id on a Library Site result. Keep the same selected workspace. Never invent, modify, or substitute another identifier.","title":"Project Id","type":"string"}},"required":["project_id"],"title":"AppgardenProjectRequest","additionalProperties":false},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false},"_meta":{"resource_name":"sites.get_environment_variables","_codex_apps":{"resource_uri":"/connector_20205bf7d4e99a89d7154bb849718324/implicit_link::connector_20205bf7d4e99a89d7154bb849718324/get_environment_variables","contains_mcp_source":false},"connector_id":"connector_20205bf7d4e99a89d7154bb849718324","connector_name":"Sites","connector_description":"Use Sites to build or modify websites, including landing pages, portfolios, dashboards, portals, trackers, hubs, and internal tools. Use Sites skills for local implementation, source preparation, and artifact packaging. Use this connector for site creation, runtime environment variables, versions, production deployments, and access controls. Read .openai/hosting.json before creating a site and reuse its project_id when present. Treat Sites IDs and cursors as opaque: copy them exactly from .openai/hosting.json or Sites responses as applicable, and never invent, reformat, derive, or substitute them. Never call create_site more than once for the same local site. Push the exact source state before saving a version. commit_sha must identify that pushed state, and any archive must be built from it. Deploy only saved versions; every Sites deployment URL is production. Inspect deployment status when the initial result is non-terminal or the user asks for progress. Publish after creating or editing a site by default, including on subsequent turns, unless the user explicitly requested local-only work, a saved version without deployment, or no publishing. New sites start private. Preserve the site's current audience unless the user explicitly requests a different audience. Use the private operation for known owner-private sites and let it enforce owner-only access. Runtime tool approvals and backend access checks still apply without a separate conversational deployment confirmation.","link_id":"implicit_link::connector_20205bf7d4e99a89d7154bb849718324"},"outputSchema":{"properties":{"project_id":{"title":"Project Id","type":"string"},"entries":{"items":{"properties":{"key":{"title":"Key","type":"string"},"value":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Value"},"is_secret":{"default":false,"title":"Is Secret","type":"boolean"},"type":{"const":"envvar","default":"envvar","title":"Type","type":"string"}},"required":["key","value"],"title":"AppgardenEnvironmentEnvVarEntryResponse","type":"object","additionalProperties":false},"title":"Entries","type":"array"},"revision":{"title":"Revision","type":"integer"},"updated_at":{"anyOf":[{"type":"string"},{"type":"null"}],"title":"Updated At"}},"required":["project_id","entries","revision","updated_at"],"title":"AppgardenEnvironmentResponse","type":"object","additionalProperties":false}},{"name":"plugin_management.get_plugin_dependencies","title":"get_plugin_dependencies","description":"Resolve the canonical public plugins declared by one plugin's app manifest. Use only when a skill or user explicitly asks for dependency metadata. Pass a plugin ID or name@marketplace reference unchanged. Named references resolve by globally listed plugin name. This reports metadata plus current user-aware plugin status, installation policy, and installed state; it does not install or connect anything. The result separates visible canonical plugins from app entries that lack a unique canonical plugin or whose canonical plugin is unavailable to the current user. This tool is part of plugin `Plugin Management`.","inputSchema":{"type":"object","properties":{"plugin_reference":{"description":"Plugin ID or name@marketplace reference whose manifest dependencies should be resolved. Pass it unchanged.","title":"Plugin Reference","type":"string"}},"required":["plugin_reference"],"title":"get_plugin_dependencies_input","additionalProperties":false},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false},"_meta":{"resource_name":"plugin_management.get_plugin_dependencies","_codex_apps":{"resource_uri":"/connector_openai_plugin_management/implicit_link::connector_openai_plugin_management/get_plugin_dependencies","contains_mcp_source":false},"connector_id":"connector_openai_plugin_management","connector_name":"Plugin Management","connector_description":"Manage plugins, settings, permissions, and connections. Prefer available built-in tools or connected plugins when they fit the task. Proactively search for plugins when an external app, account, or service would materially help, even if the user did not request a plugin. Search before claiming a service is unavailable or suggesting manual workarounds. Do not suggest plugins for native web search, image generation, memory, or sites unless a specific external provider or missing capability is needed.","link_id":"implicit_link::connector_openai_plugin_management"}},{"name":"codex_document_control.execute_document_command","title":"execute_document_command","description":"Execute one supported surface-specific tool against a connected Codex document session. First call `list_document_sessions` to choose the intended `executor_session_id` and `supported_tools[].name`, then call `get_document_tool_schemas` for the selected `surface`, that `supported_tools[].name` as `tool_name`, and `version` before constructing `args`. `idempotency_key` must be a caller-stable key that you reuse verbatim only when retrying the same logical document-control command; use a new key for a different command. This tool is part of plugin `Spreadsheets`.","inputSchema":{"type":"object","properties":{"executor_session_id":{"description":"Exact `executor_session_id` copied from the selected Codex document session returned by `list_document_sessions`.","title":"Executor Session Id","type":"string"},"idempotency_key":{"description":"Caller-stable idempotency key for this logical document-control command. Reuse the exact same key only for retries of the same command.","maxLength":512,"minLength":1,"title":"Idempotency Key","type":"string"},"tool_name":{"description":"Exact selected session `supported_tools[].name` copied from `list_document_sessions`.","title":"Tool Name","type":"string"},"args":{"additionalProperties":{},"description":"JSON object of arguments matching the selected tool's `input_schema` from `get_document_tool_schemas`.","title":"Args","type":"object"}},"required":["executor_session_id","idempotency_key","tool_name","args"],"title":"execute_document_command_input","additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false},"_meta":{"resource_name":"codex_document_control.execute_document_command","_codex_apps":{"resource_uri":"/connector_openai_codex_document_control/implicit_link::connector_openai_codex_document_control/execute_document_command","contains_mcp_source":false},"connector_id":"connector_openai_codex_document_control","connector_name":"Codex Document Control","connector_description":"Use Codex Document Control to find connected document sessions, inspect the tools supported by a selected session, and execute one supported tool against that session. Call `list_document_sessions` first to choose the intended connected session, call `get_document_tool_schemas` before constructing tool arguments, then call `execute_document_command` with a caller-stable `idempotency_key`. Use this only for connected Codex document control; do not use it for general spreadsheet, presentation, or document tasks without a connected document session.","link_id":"implicit_link::connector_openai_codex_document_control"}},{"name":"sites.generate_siwc_bypass_token","title":"generate_siwc_bypass_token","description":"Generate a bearer token for identity-less API requests that bypasses a site's Sign in with ChatGPT gate. Call this explicit token tool only when the user asks for a bypass token. Calling this tool creates a token if none exists, or rotates and immediately invalidates the existing token. Pass the returned token as OAI-Sites-Authorization: Bearer {siwc_bypass_bearer_token}. This tool is part of plugin `Sites`.","inputSchema":{"type":"object","properties":{"project_id":{"description":"Exact opaque site project ID. Copy it verbatim from .openai/hosting.json's project_id or the id field returned by create_site, list_sites, or get_site, or the server-returned site_metadata.project_id on a Library Site result. Keep the same selected workspace. Never invent, modify, or substitute another identifier.","title":"Project Id","type":"string"}},"required":["project_id"],"title":"AppgardenProjectRequest","additionalProperties":false},"annotations":{"readOnlyHint":fal