rties":{"project_id":{"title":"Project Id","type":"string"},"siwc_bypass_bearer_token":{"description":"Bearer token accepted by Sites dispatch in the OAI-Sites-Authorization header.","title":"Siwc Bypass Bearer Token","type":"string"}},"required":["project_id","siwc_bypass_bearer_token"],"title":"AppgardenSiwcBypassTokenResponse","type":"object","additionalProperties":false}}]},{"hostId":"local","icon":null,"pluginId":null,"server":"computer-use","tools":[]},{"hostId":"local","icon":null,"pluginId":null,"server":"cua_repl","tools":[]},{"hostId":"local","icon":null,"pluginId":null,"server":"node_repl","tools":[{"name":"js","description":"Execute JavaScript in a persistent `node_repl` with top-level await. Top-level bindings persist until `js_reset` and can be redeclared. Use `const` for stable values and `let` for changing values. Use dynamic imports such as `await import(\"playwright\")`; top-level static imports and `node:process` are unavailable. Use `nodeRepl.write(value)` for output and `await nodeRepl.emitImage(image)` for images. Execution context is available through `nodeRepl.cwd`, `nodeRepl.homeDir`, `nodeRepl.tmpDir`, and `nodeRepl.requestMeta`. The default timeout is 30000 ms (30 seconds); increase `timeout_ms` for longer operations. Use `js_add_node_module_dir` when an additional package directory is required.","inputSchema":{"type":"object","properties":{"code":{"description":"JavaScript code to execute with top-level await.","type":"string"},"timeout_ms":{"description":"Optional execution timeout in milliseconds. Defaults to 30000 (30 seconds) when omitted.","minimum":1,"type":"integer"},"title":{"description":"Short user-facing description of what the code does.","maxLength":80,"minLength":1,"type":"string"}},"required":["code"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false}},{"name":"js_add_node_module_dir","description":"Add an absolute `node_modules` directory for package imports. The directory remains available after `js_reset`.","inputSchema":{"type":"object","properties":{"path":{"description":"Absolute path to a node_modules directory to add to Node package resolution.","minLength":1,"type":"string"}},"required":["path"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false}},{"name":"js_reset","description":"Reset the JavaScript kernel and clear all bindings.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":true,"destructiveHint":false,"openWorldHint":false}},{"name":"turn_ended","description":"Notify trusted libraries that a Codex turn ended. Repeated notifications for the same session and turn are ignored.","inputSchema":{"type":"object","properties":{"hook_event_name":{"minLength":1,"type":"string"},"session_id":{"minLength":1,"type":"string"},"turn_id":{"minLength":1,"type":"string"}},"required":["hook_event_name","session_id","turn_id"],"additionalProperties":false},"annotations":{"idempotentHint":true},"_meta":{"ui":{"visibility":[]}}}]},{"hostId":"local","icon":null,"pluginId":null,"server":"playwright","tools":[{"name":"browser_find","description":"Search the accessibility snapshot of the current page for text or a regular expression. Returns matching snapshot nodes with a few lines of surrounding context (like search snippets), each shown under its path from the root of the tree, which is cheaper than capturing the whole snapshot when you only need to locate an element and its ref.","inputSchema":{"type":"object","properties":{"text":{"description":"Plain text to search for in the page snapshot (case-insensitive substring match). Provide either text or regex, not both.","type":"string"},"regex":{"description":"Regular expression to search for in the page snapshot. Matching is case-sensitive by default; wrap the pattern in slashes to add flags, e.g. \"/error/i\" for case-insensitive. Provide either text or regex, not both.","type":"string"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Find in page snapshot","readOnlyHint":true,"destructiveHint":false,"openWorldHint":true}},{"name":"browser_network_request","description":"Returns full details (headers and body) of a single network request, or a single part if `part` is set. Use the number from browser_network_requests.","inputSchema":{"type":"object","properties":{"index":{"type":"integer","minimum":1,"maximum":9007199254740991,"description":"1-based index of the request, as printed by browser_network_requests."},"part":{"description":"Return only this part of the request. Omit to return full details.","type":"string","enum":["request-headers","request-body","response-headers","response-body"]},"filename":{"description":"File name to save the result to. Relative file names are resolved against the workspace root. If not provided, output is returned as text.","type":"string"}},"required":["index"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Show network request details","readOnlyHint":true,"destructiveHint":false,"openWorldHint":true}},{"name":"browser_resize","description":"Resize the browser window","inputSchema":{"type":"object","properties":{"width":{"type":"number","description":"Width of the browser window"},"height":{"type":"number","description":"Height of the browser window"}},"required":["width","height"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Resize browser window","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_snapshot","description":"Capture accessibility snapshot of the current page, this is better than screenshot","inputSchema":{"type":"object","properties":{"target":{"description":"Exact target element reference from the page snapshot, or a unique element selector","type":"string"},"filename":{"description":"Save snapshot to a file instead of returning it in the response. Relative file names are resolved against the workspace root.","type":"string"},"depth":{"description":"Limit the depth of the snapshot tree","type":"number"},"boxes":{"description":"Include each element's bounding box as [box=x,y,width,height] in the snapshot. Coordinates are viewport-relative, in CSS pixels (Element.getBoundingClientRect)","type":"boolean"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Page snapshot","readOnlyHint":true,"destructiveHint":false,"openWorldHint":true}},{"name":"browser_tabs","description":"List, create, close, or select a browser tab.","inputSchema":{"type":"object","properties":{"action":{"type":"string","enum":["list","new","close","select"],"description":"Operation to perform"},"index":{"description":"Tab index, used for close/select. If omitted for close, current tab is closed.","type":"number"},"url":{"description":"URL to navigate to in the new tab, used for new.","type":"string"}},"required":["action"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Manage tabs","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_run_code_unsafe","description":"Run a Playwright code snippet. Unsafe: executes arbitrary JavaScript in the Playwright server process and is RCE-equivalent.","inputSchema":{"type":"object","properties":{"code":{"description":"A JavaScript function containing Playwright code to execute. It will be invoked with a single argument, page, which you can use for any page interaction. For example: `async (page) => { await page.getByRole('button', { name: 'Submit' }).click(); return await page.title(); }`","type":"string"},"filename":{"description":"Load code from the specified file. Relative file names are resolved against the workspace root. If both code and filename are provided, code will be ignored.","type":"string"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Run Playwright code (unsafe)","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_type","description":"Type text into editable element","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"text":{"type":"string","description":"Text to type into the element"},"submit":{"description":"Whether to submit entered text (press Enter after)","type":"boolean"},"slowly":{"description":"Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once.","type":"boolean"}},"required":["target","text"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Type text","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_console_messages","description":"Returns all console messages","inputSchema":{"type":"object","properties":{"level":{"default":"info","description":"Level of the console messages to return. Each level includes the messages of more severe levels. Defaults to \"info\".","type":"string","enum":["error","warning","info","debug"]},"all":{"description":"Return all console messages since the beginning of the session, not just since the last navigation. Defaults to false.","type":"boolean"},"filename":{"description":"File name to save the console messages to. Relative file names are resolved against the workspace root. If not provided, messages are returned as text.","type":"string"}},"required":["level"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Get console messages","readOnlyHint":true,"destructiveHint":false,"openWorldHint":true}},{"name":"browser_file_upload","description":"Upload one or multiple files","inputSchema":{"type":"object","properties":{"paths":{"description":"The absolute paths to the files to upload. Can be single file or multiple files. If omitted, file chooser is cancelled.","type":"array","items":{"type":"string"}}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Upload files","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_fill_form","description":"Fill multiple form fields","inputSchema":{"type":"object","properties":{"fields":{"type":"array","items":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"name":{"type":"string","description":"Human-readable field name"},"type":{"type":"string","enum":["textbox","checkbox","radio","combobox","slider"],"description":"Type of the field"},"value":{"type":"string","description":"Value to fill in the field. If the field is a checkbox, the value should be `true` or `false`. If the field is a combobox, the value should be the text of the option."}},"required":["target","name","type","value"],"additionalProperties":false},"description":"Fields to fill in"}},"required":["fields"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Fill form","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_click","description":"Perform click on a web page","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"doubleClick":{"description":"Whether to perform a double click instead of a single click","type":"boolean"},"button":{"description":"Button to click, defaults to left","type":"string","enum":["left","right","middle"]},"modifiers":{"description":"Modifier keys to press","type":"array","items":{"type":"string","enum":["Alt","Control","ControlOrMeta","Meta","Shift"]}}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Click","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_hover","description":"Hover over element on page","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false},"annotations":{"title":"Hover mouse","readOnlyHint":false,"destructiveHint":true,"openWorldHint":true}},{"name":"browser_evaluate","description":"Evaluate JavaScript expression on page or element","inputSchema":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"description":"Exact target element reference from the page snapshot, or a unique element selector","type":"string"},"function":{"type":"string","description":"() => { /* code */ } or (element) => { /* code */ } when element is provided"},"filename":{"description":"File name to save the result to. Relative file names are resolved against the workspace root. If not provided, result is returned as text