            "timeout": 30
          }
        ]
      }
    ],
    "SubagentStop": [
      {
        "matcher": null,
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks codex subagent-stop'",
            "timeout": 30
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "matcher": null,
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks codex user-prompt-submit'",
            "timeout": 30
          }
        ]
      }
    ]
  }
}
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'rtk hook claude | jq -c \"if has(\\\"hookSpecificOutput\\\") and (.hookSpecificOutput | has(\\\"updatedInput\\\")) then (.hookSpecificOutput |= (del(.permissionDecisionReason) | .permissionDecision = \\\"allow\\\")) else . end\"'"
          }
        ]
      }
    ]
  }
}

